/**
 * === Map leaves → points (API unit as source of truth) =======================
 * Converts Lindinspect leaves to normalized point objects.
 * Unit is ALWAYS taken from API (leaf.unit) and normalized.
 * No subject-based unit inference is performed.
 *
 * Inputs:
 *   msg.payload = { leaves: [...] } | [...] | { ...singleLeaf }
 *   msg.nodeMeta = { id, label, ... }
 *
 * Outputs:
 *   msg.payload = point[]
 * ============================================================================
 */

const creds = global.get('config', 'persistent') || {};
const PROPERTY = creds.property;                       // Static property identifier
const SOURCE   = `${PROPERTY}_LINDINSPECT`;

// ---------- Helpers -----------------------------------------------------------
const toStr   = (v) => (v ?? '').toString();
const normStr = (s) => toStr(s).trim();
const normInt = (v) => Number.isFinite(Number(v)) ? Number(v) : 0;

// Soft text clean (diacritics, zero-width, bullets, NBSP, spacing)
function softClean(sRaw) {
  return toStr(sRaw)
    .normalize('NFKC')
    .replace(/\u00A0/g, ' ')           // NBSP → space
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/º/g, '°')                // unify degree
    .replace(/[·•]/g, '')              // remove middle dot / bullets
    .replace(/\s+/g, ' ')
    .trim();
}

// Canonical, readable subject (no filtering is done here)
function canonicalSubject(subjectRaw) {
  const n0 = softClean(subjectRaw).replace(/_/g, ' ');
  if (!n0) return '';
  // Trim trailing dot artifacts (e.g., 'Tryck·' -> 'Tryck')
  const n1 = n0.replace(/[·•]\s*$/u, '').trim();
  // Title-case words to make it consistent/readable
  return n1.replace(/\p{L}+/gu, (w) => w[0].toUpperCase() + w.slice(1).toLowerCase());
}

// Normalize known/alias units to a consistent set
function normalizeUnit(uRaw) {
  const u = softClean(uRaw);
  if (!u) return '';

  // Already in canonical set?
  const whitelist = new Set(['°C', 'l/s', 'Pa', '%', 'W', 'V', 'ppm', 'min', 's', 'hrs', '']);
  if (whitelist.has(u)) return u;

  // Common aliases → canonical
  const lut = new Map([
    ['c', '°C'], ['°c', '°C'], ['degc', '°C'], ['° c', '°C'],
    ['ls', 'l/s'], ['lps', 'l/s'],
    ['pa', 'Pa'],
    ['percent', '%'],
    ['w', 'W'],
    ['v', 'V'],
    ['ppm', 'ppm'],
    ['min', 'min'],
    ['sec', 's'], ['sek', 's'], ['s', 's'],
    ['h', 'hrs'], ['hr', 'hrs'], ['hour', 'hrs'], ['hours', 'hrs'], ['tim', 'hrs']
  ]);

  const key = u.toLowerCase();
  return lut.get(key) || u; // fallback: keep original if unknown
}

// ---------- Main --------------------------------------------------------------
try {
  const nodeId    = msg?.nodeMeta?.id ?? null;
  const labelBase = msg?.nodeMeta?.label ?? null;

  // Normalize leaves input to an array
  let leaves = [];
  if (Array.isArray(msg?.payload?.leaves))      leaves = msg.payload.leaves;
  else if (Array.isArray(msg?.payload))         leaves = msg.payload;
  else if (msg?.payload && typeof msg.payload === 'object') leaves = [msg.payload];

  if (!nodeId) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'Missing nodeId' });
    msg.payload = [];
    return msg;
  }
  if (!Array.isArray(leaves) || leaves.length === 0) {
    node.status({ fill: 'grey', shape: 'dot', text: 'No leaves' });
    msg.payload = [];
    return msg;
  }

  // 1) Build normalized point objects
  const points = [];
  let missingUnitCount = 0;

  for (let i = 0; i < leaves.length; i++) {
    const leaf = leaves[i];
    const subjExact = normStr(leaf?.name);
    if (!subjExact) continue;

    const subjectCanonical = canonicalSubject(subjExact);
    const label = labelBase ? `${labelBase}_${subjExact}` : subjExact;

    // Unit: take from API only, normalize; do NOT infer from subject
    const apiUnitNormalized = normalizeUnit(leaf?.unit ?? '');
    if (!apiUnitNormalized) missingUnitCount++;

    const p = {
      // labels & subject
      label,
      'description': subjExact,

      // attributes from API (unit is source of truth)
      'unit': apiUnitNormalized,
      'writable': !!leaf?.writable,
      'toStream': "Unknown",   // "Unknown" | "true" | "false"
      'deprecated': false, 

      // domain fields
      'source': SOURCE,
      'property': PROPERTY,
      'floor': 1,
      'zone': '',
      'room': normInt(extractRoomFromContext(leaves)), // see context extraction below
      'system': normStr(extractSystemFromContext(leaves)),
      'component': normStr(extractComponentFromContext(leaves)),
      'system_id': extractSystemFromContext(leaves) ? `${PROPERTY}_${normStr(extractSystemFromContext(leaves))}` : '',
      'component_id': (extractSystemFromContext(leaves) && extractComponentFromContext(leaves))
        ? `${PROPERTY}_${normStr(extractSystemFromContext(leaves))}_${normStr(extractComponentFromContext(leaves))}` : '',


      // identifiers
      'lindinspectid': nodeId,
      'leafId': (leaf?.id !== undefined && leaf?.id !== null) ? String(leaf.id) : `${nodeId}:${i}`,
    };

    points.push(p);
  }

  node.status({
    fill: 'green',
    shape: 'dot',
    text: `points: ${points.length} units_missing_from_API: ${missingUnitCount}`
  });

  msg.payload = points;
  return msg;

} catch (err) {
  node.status({ fill: 'red', shape: 'ring', text: 'Error in Map leaves → points' });
  node.error(err, msg);
  msg.payload = { error: String(err) };
  return msg;
}

/* -------- Context extraction helpers (unchanged behavior) ------------------ */
function extractContextFromLeaves(leaves) {
  const ctx = { system: '', component: '', room: 0, productType: 'BCX' };
  for (const leaf of leaves) {
    const name = toStr(leaf?.name);
    if (name === 'Beteckning' && leaf?.stringValue) {
      const s = toStr(leaf.stringValue);
      // Formats:
      //   LB11-TB11:058-1203
      //   LB11-TB11:58-1203
      //   LB11-TB/XX11:058-1203
      const m =
        s.match(/^(LB\d{2})-([A-Z]{2}\d{2}:[\d/]+)-(\d{3,4})$/) ||
        s.match(/^(LB\d{2})-([A-Z]{2}\/?[A-Z]*\d{2}:[\d/]+)-(\d{3,4})$/);
      if (m) {
        ctx.system    = m[1];
        ctx.component = m[2];
        ctx.room      = Number(m[3]) || 0;
      }
    }
    if (name === 'Produktförkortning' && leaf?.stringValue) {
      ctx.productType = toStr(leaf.stringValue).trim() || ctx.productType;
    }
  }
  return ctx;
}
function extractSystemFromContext(leaves){ return extractContextFromLeaves(leaves).system; }
function extractComponentFromContext(leaves){ return extractContextFromLeaves(leaves).component; }
function extractRoomFromContext(leaves){ return extractContextFromLeaves(leaves).room; }

// === Flatten, keep ALL subjects, compute HASH (with property), persist =======
// - Stores ALL points under genericGrossList[Git].nodeff[Lindinspect_controller]
// - Computes deterministic HASH = sha256(property + '|' + lindinspectid + '|' + description)
// - Preserves toStream ("Unknown" | true | false) and deprecated (boolean)
// - Updates lastSeen (ISO timestamp) on every inventory rebuild
// =============================================================================

const STORE = 'persistent';
const deviceKey = 'Git';
const controllerKey = 'Lindinspect_controller';

function flattenDeep(arr) {
  if (!Array.isArray(arr)) return [];
  return arr.flat ? arr.flat(Infinity)
    : arr.reduce((acc, x) => acc.concat(Array.isArray(x) ? flattenDeep(x) : [x]), []);
}

function computeHash(property, lindId, description) {
  const input = `${String(property || '')}|${String(lindId || '')}|${String(description || '')}`;
  try {
    const crypto = require('crypto');
    return crypto.createHash('sha256').update(input).digest('hex');
  } catch {
    let h = 5381;
    for (let i = 0; i < input.length; i++) h = ((h << 5) + h) + input.charCodeAt(i);
    h >>>= 0;
    return ('00000000' + h.toString(16)).slice(-8);
  }
}

// Identity key used for preservation (must match HASH input)
function identityKey(p) {
  return `${String(p?.property ?? '')}|${String(p?.lindinspectid ?? '')}|${String(p?.description ?? '')}`;
}

// Optional: normalize legacy string values -> desired model
function normalizeToStream(v) {
  if (v === "Unknown" || v === true || v === false) return v;
  if (typeof v === "string") {
    const s = v.trim().toLowerCase();
    if (s === "true") return true;
    if (s === "false") return false;
    if (s === "unknown") return "Unknown";
  }
  return "Unknown";
}

// 1) Normalize to an array
let list = Array.isArray(msg.payload)
  ? flattenDeep(msg.payload)
  : (msg.payload && typeof msg.payload === 'object') ? [msg.payload] : [];

const before = list.length;
const allPoints = list;

// Timestamp for this rebuild
const nowIso = new Date().toISOString();

// 2) Load existing inventory BEFORE overwriting, build preserve index
const existingInventory = global.get('genericGrossList', STORE) || {};
const existingPoints =
  existingInventory?.[deviceKey]?.nodeff?.[controllerKey]?.points || [];

const preserve = new Map(); // identityKey -> { toStream, deprecated }
if (Array.isArray(existingPoints)) {
  for (const ep of existingPoints) {
    if (!ep) continue;
    preserve.set(identityKey(ep), {
      toStream: ep.toStream,
      deprecated: ep.deprecated
    });
  }
}

// 3) Compute HASH + re-apply preserved fields (or defaults) + lastSeen
for (const p of allPoints) {
  p.HASH = computeHash(p.property, p.lindinspectid, p.description);

  const prev = preserve.get(identityKey(p));

  // Preserve if previously set, otherwise defaults
  const prevToStream = prev?.toStream;
  const prevDeprecated = prev?.deprecated;

  p.toStream = (prevToStream !== undefined)
    ? normalizeToStream(prevToStream)
    : (p.toStream !== undefined ? normalizeToStream(p.toStream) : "Unknown");

  p.deprecated = (prevDeprecated !== undefined)
    ? !!prevDeprecated
    : (p.deprecated !== undefined ? !!p.deprecated : false);

  // Always updated on rebuild
  p.lastSeen = nowIso;
}

// 4) Persist inventory (genericGrossList)
const inventory = existingInventory;
inventory[deviceKey] ??= {};
inventory[deviceKey].nodeff ??= {};
inventory[deviceKey].nodeff[controllerKey] ??= {};

const ctrl = inventory[deviceKey].nodeff[controllerKey];
ctrl.integrationType = 'Lindinspect';
ctrl.points = allPoints;
ctrl.updatedAt = nowIso;

global.set('genericGrossList', inventory, STORE);

// 5) Diagnostics: detect duplicate HASH groups
const hashCount = new Map();
for (const p of allPoints) {
  const h = String(p?.HASH ?? '').trim();
  if (!h) continue;
  hashCount.set(h, (hashCount.get(h) || 0) + 1);
}

const dupHashes = [];
for (const [h, c] of hashCount.entries()) {
  if (c > 1) {
    const plist = allPoints.filter(pp => String(pp?.HASH ?? '').trim() === h);
    dupHashes.push({
      hash: h,
      count: c,
      nodes: plist.map(pp => `${pp.property}|${pp.lindinspectid}|${pp.description}`)
    });
  }
}
dupHashes.sort((a, b) => b.count - a.count);

node.status({
  fill: dupHashes.length ? 'yellow' : 'green',
  shape: 'dot',
  text: `saved ${allPoints.length}/${before} hash_dups:${dupHashes.length}`
});

msg.inventory = inventory;
msg.payload = {
  saved: allPoints.length,
  total: before,
  lastSeen: nowIso,
  duplicate_hash_groups: dupHashes.slice(0, 10),
  path: `inventory["${deviceKey}"].nodeff.${controllerKey}.points`
};

return msg;

// === Auth + Base URL ==========================================================
// Reads credentials from persistent global context and constructs a normalized
// base URL for the Lindinspect API. Also prepares Basic Auth and Accept headers
// to be reused by downstream HTTP Request nodes.
//
// Expected global context (persistent):
//   credentials = {
//     scheme: "http" | "https",
//     host: "<host>",
//     port: <number>,
//     user: "<user>",
//     pass: "<pass>",
//     // optional:
//     baseUrl: "http(s)://host:port"
//   }
//
// Side effects:
//   flow.lind_baseUrl = "<scheme>://<host>:<port>/api/v1"
//   msg.headers, msg.method, msg.url
// =========================================================================

const creds = global.get('config', 'persistent') || {};
const scheme = (creds.scheme || 'http').toLowerCase();
const host   = creds.host || '127.0.0.1';
const port   = (creds.port != null) ? String(creds.port) : (scheme === 'https' ? '443' : '80');

// Prefer baseUrl if provided; ensure trailing /api/v1
let base = creds.baseUrl || `${scheme}://${host}:${port}`;
base = base.replace(/\/+$/,'');
if (!/\/api\/v1$/i.test(base)) base += '/api/v1';

// Persist normalized base URL for subsequent requests in this flow
flow.set('lind_baseUrl', base);

// Build Basic Auth header from user/pass
const user = creds.user || '';
const pass = creds.pass || '';
const token = Buffer.from(`${user}:${pass}`).toString('base64');

// Prepare request to GET /nodes
msg.method = 'GET';
msg.url = `${base}/nodes`;
msg.headers = {
  'Authorization': `Basic ${token}`,
  'Accept': 'application/json',
  'Connection': 'close'
};

return msg;

// === Build leaf request =======================================================
// For each Lindinspect node (from Split), prepare GET /nodes/{id}/leaves.
// Reuses base URL from flow context. Uses Basic Auth from global credentials.
// Adds a short randomized delay (jitter) to avoid burst load.
// Carries node metadata forward via msg.nodeMeta.
// =========================================================================

const currentNode = msg.payload;
if (!currentNode?.id) {
  node.error("Current node is missing 'id' in msg.payload");
  return null;
}

const baseUrl = flow.get('lind_baseUrl');
if (!baseUrl) {
  node.error("Missing flow.lind_baseUrl. Run 'Auth + Base URL' first.");
  return null;
}

// Basic Auth from credentials
const creds = global.get('config','persistent') || {};
const user  = creds.user || '';
const pass  = creds.pass || '';
const token = Buffer.from(`${user}:${pass}`).toString('base64');

// Prepare HTTP GET /nodes/{id}/leaves
msg.method   = "GET";
msg.url      = `${baseUrl}/nodes/${encodeURIComponent(String(currentNode.id))}/leaves`;
msg.nodeMeta = currentNode; // carry node meta forward

msg.headers = {
  Accept: "application/json",
  Authorization: `Basic ${token}`,
  Connection: "close"
};

// Add short randomized delay (200–400 ms) to spread load
const baseDelay = 200 + Math.floor(Math.random() * 200);
node.status({
  fill: "yellow",
  shape: "dot",
  text: `→ node ${currentNode.id} (delay ${baseDelay} ms)`
});

return new Promise((resolve) => {
  setTimeout(() => resolve(msg), baseDelay);
});
